import sqlite3

def handle(query, state):
    flag = state.get("flag", "")
    product = (query.get("product") or [""])[0]

    conn = sqlite3.connect(":memory:")
    cur = conn.cursor()

    cur.execute(
        "CREATE TABLE products (id INTEGER PRIMARY KEY, name TEXT, price REAL, category TEXT)"
    )
    cur.execute(
        "CREATE TABLE reviews (id INTEGER PRIMARY KEY, product_id INTEGER, author TEXT, comment TEXT)"
    )
    cur.executemany(
        "INSERT INTO products (name, price, category) VALUES (?, ?, ?)",
        [
            ("Laptop", 999.99, "Electronics"),
            ("Mouse", 29.99, "Electronics"),
            ("Keyboard", 79.99, "Electronics"),
        ],
    )
    cur.executemany(
        "INSERT INTO reviews (product_id, author, comment) VALUES (?, ?, ?)",
        [
            (1, "alice", "Great product"),
            (1, "bob", flag),
            (2, "charlie", "Works well"),
        ],
    )
    conn.commit()

    sql = "SELECT id, name, price FROM products WHERE name LIKE '%" + product + "%'"
    try:
        cur.execute(sql)
        rows = cur.fetchall()
    except sqlite3.Error as e:
        conn.close()
        return 500, {"Content-Type": "text/plain"}, "DB error: " + str(e)

    conn.close()

    if not rows:
        return 200, {"Content-Type": "text/plain"}, "No products found."

    lines = []
    for row in rows:
        lines.append("|".join(str(c) for c in row))
    return 200, {"Content-Type": "text/plain"}, "\n".join(lines)
